   15 | 	    return SUCCESS;
   16 | 	if (agmapnametoid(agroot(g), AGTYPE(obj), newname,
   17 | 			  &new_id, TRUE) == 0)
   18 | 	    return FAILURE;
   19 |         /* obj* is unchanged, so no need to re agregister() */
   20 | 	if (agparent(g) && agidsubg(agparent(g), new_id, 0))
   21 | 	    return FAILURE;
   22 | 	agfreeid(g, AGRAPH, old_id);
   23 | 	AGID(g) = new_id;
   24 | 	break;
   25 |     case AGNODE:
   26 | 	return agrelabel_node((Agnode_t *) obj, newname);
   27 | 	agrename(obj, newname);
   28 | 	break;
   29 |     case AGINEDGE:
   30 |     case AGOUTEDGE:
   31 | 	return FAILURE;
   32 |     }
   33 |     return SUCCESS;
   34 | }
